#include <vector>
#include <omp.h>

/* Return the product of the vector x with every odd indexed element inverted.
   i.e. x_0 * 1/x_1 * x_2 * 1/x_3 * x_4 ...
   The computation is performed in parallel with OpenMP and is correct for any
   number of threads.
*/
double productWithInverses(const std::vector<double>& x) {
    // The neutral element for multiplication.
    double product = 1.0;

    // Parallel loop with a multiplication reduction.
    #pragma omp parallel for reduction(*:product) schedule(static)
    for (std::size_t i = 0; i < x.size(); ++i) {
        double term = (i % 2 == 0) ? x[i] : 1.0 / x[i];
        product *= term;
    }

    return product;
}
